entropy loss\\n    # Using jax.nn.sigmoid_binary_cross_entropy or similar is better for stability\\n    # But let's write it out or use a stable version.\\n    # loss = -jnp.mean(y * jax.nn.log_sigmoid(logits) + (1 - y) * jnp.log(1 - jax.nn.sigmoid(logits)))\\n    # More stable: \\n    max_val = jnp.maximum(0, logits)\\n    loss = jnp.mean(max_val - logits * y + jnp.log(1 + jnp.exp(-jnp.abs(logits))))\\n    return loss\\n\\ndata_log = np.load('data/logistic.npz')\\nx_log, y_log, w_log = data_log['x'], data_log['y'], data_log['w']\\ngrad_fn = jax.grad(logistic_loss)\\nres3 = grad_fn(w_log, x_log, y_log)\\nnp.save('grad_logistic.npy', np.array(res3))\\n\\n# 4. scan_rnn\\n# Implement RNN forward pass using scan.\\n# h_t = tanh(h_{t-1} W_h + x_t W_x + b)\\ndata_seq = np.load('data/seq.npz')\\nseq, h_init, Wx, Wh, b = data_seq['seq'], data_seq['init'], data_seq['Wx'], data_seq['Wh'], data_seq['b']\\n\\ndef rnn_step(h, x):\\n    h_next = jnp.tanh(jnp.dot(h, Wh) + jnp.dot(x, Wx) + b)\\n    return h_next, h_next\\n\\n_, h_seq = jax.lax.scan(rnn_step, h_init, seq)\\nnp.save('scan_rnn.npy', np.array(h_seq))\\n\\n# 5. jit_mlp\\n# Implement and JIT compile a 2-layer MLP.\\ndata_mlp = np.load('data/mlp.npz')\\nX_mlp, W1, b1, W2, b2 = data_mlp['X'], data_mlp['W1'], data_mlp['b1'], data_mlp['W2'], data_mlp['b2']\\n\\n@jax.jit\\ndef mlp(X, W1, b1, W2, b2):\\n    layer1 = jax.nn.relu(jnp.dot(X, W1) + b1)\\n    layer2 = jnp.dot(layer1, W2) + b2\\n    return layer2\\n\\nres5 = mlp(X_mlp, W1, b1, W2, b2)\\nnp.save('jit_mlp.npy', np.array(res5))\\nEOF\\n\",\n      \"duration\": 1.0\n    },\n    {\n      \"keystrokes\": \"python3 solve_tasks.py\\n\",\n      \"duration\": 2.0\n    }\n  ]\n}"
